        uint256 len = data.length;
        if (len >= 32) {
            revert ContentTooLarge(len);
        }

        assembly {
            // Pack: tag byte (len+1) | first 31 bytes of data
            packed :=
                or(
                    shl(248, add(len, 1)), // Tag in first byte
                    shr(8, mload(add(data, 0x20))) // Data in remaining 31 bytes (skip length prefix)
                )
        }
    }

